package tokencheck

/*
 * Dimension-catalog contract ↔ assertion map (dim-token chunk 1).
 *
 * The catalog (dim-catalog.json, generated by tools/dim-catalog.mjs) is the
 * single source of the v1 dimension surface: 19 writable tokens (spacing 4,
 * layout 7, type 8 = 4 sizes + 4 line-heights) plus docked-min locked as the
 * derived sum. Every range below comes from the census Q6 table
 * (scratch/dimwave/census.md); the relation list comes from the chunk-1 spec
 * with the type-step ≥2px gap carried from the census.
 *
 *	contract                              assertion
 *	────────────────────────────────────  ─────────────────────────────────────
 *	catalog axes and tiers are as shipped TestDimCatalogShape
 *	docked-min default is the derived sum TestDimCatalogShape
 *	defaults sit inside their own ranges  TestDimCatalogShape
 *	px lengths: int/1-decimal, positive  TestDimParseLength
 *	line-heights: unitless 1–2 decimals   TestDimParseUnitless
 *	valid partial overrides pass          TestValidateDimensionsAccepts
 *	unknown axis/token carried + warned   TestValidateDimensionsUnknownCarried
 *	locked docked-min refuses writes      TestValidateDimensionsLocked
 *	bad length refused; range warns       TestValidateDimensionsValues
 *	relations warn against defaults       TestValidateDimensionsRelations
 *	range/relation values participate     TestRangeAndRelationValuesStillJudge
 *	boundary values accept                TestValidateDimensionsBoundaries
 *	deterministic output                  TestDimDeterminism
 *
 * GDK-858 (user decision 2026-08-25): range and relation violations are
 * judgments about tested territory and visual rhythm, not machine-checkable
 * shapes — they WARN and the value is carried. The length grammar and the
 * derived docked-min keep refusing: a value that cannot parse can never
 * render, and a stored docked-min would be overwritten by the recomputation.
 */

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

func TestDimCatalogShape(t *testing.T) {
	axes := DimAxes()
	if !reflect.DeepEqual(axes, []string{"spacing", "layout", "type"}) {
		t.Fatalf("DimAxes() = %v, want [spacing layout type]", axes)
	}
	doc := struct {
		Axes []struct {
			ID     string              `json:"id"`
			Tokens map[string]DimToken `json:"tokens"`
		} `json:"axes"`
	}{}
	if err := json.Unmarshal(dimCatalogJSON, &doc); err != nil {
		t.Fatalf("dim-catalog.json does not parse: %v", err)
	}
	byID := map[string]map[string]DimToken{}
	for _, ax := range doc.Axes {
		if _, dup := byID[ax.ID]; dup {
			t.Fatalf("axis %s listed twice", ax.ID)
		}
		byID[ax.ID] = ax.Tokens
	}
	locked := 0
	var sum float64
	have := map[string]bool{}
	for _, axis := range axes {
		toks := byID[axis]
		if len(toks) == 0 {
			t.Fatalf("axis %s is empty in dim-catalog.json", axis)
		}
		for name, tok := range toks {
			if tok.CSSVar == "" {
				t.Errorf("%s.%s has no cssVar", axis, name)
			}
			if tok.Tier != "validated-range" && tok.Tier != "locked" {
				t.Errorf("%s.%s tier %q is not validated-range or locked", axis, name, tok.Tier)
			}
			switch tok.Unit {
			case "px", "none":
			default:
				t.Errorf("%s.%s unit %q must be px or none", axis, name, tok.Unit)
			}
			if tok.Tier == "locked" {
				locked++
				if name != "docked-min" || axis != "layout" {
					t.Errorf("locked token %s.%s — v1 locks only layout.docked-min", axis, name)
				}
				continue
			}
			v, ok := tok.ParseValue(tok.Default)
			if !ok {
				t.Errorf("%s.%s default %q does not parse", axis, name, tok.Default)
				continue
			}
			if tok.Min != nil && v < *tok.Min {
				t.Errorf("%s.%s default %g is below its own min %g", axis, name, v, *tok.Min)
			}
			if tok.Max != nil && v > *tok.Max {
				t.Errorf("%s.%s default %g is above its own max %g", axis, name, v, *tok.Max)
			}
			switch axis + "." + name {
			case "layout.sidebar", "layout.list-min", "layout.detail-min":
				sum += v
			}
			have[axis+"."+name] = true
		}
	}
	if locked != 1 {
		t.Errorf("locked dimension tokens = %d, want 1 (docked-min)", locked)
	}
	// 2026-08-25 — GDK-864: 19 → 20, type.terminal. Not a loosened bound:
	// this census exists so the override surface grows on purpose, and the
	// growth is one token that lets a person or an agent set the terminal's
	// text size (`ui.tokens.type.terminal`) without dragging the app's body
	// scale with it. FAIL-first: adding the token to the catalog made this
	// line read "writable dimension tokens = 20, want 19" before it moved.
	if len(have) != 20 {
		t.Errorf("writable dimension tokens = %d, want 20 (have %v)", len(have), have)
	}
	tok, ok := DimTokenOf("layout", "docked-min")
	if !ok {
		t.Fatal("docked-min missing from catalog")
	}
	v, _ := tok.ParseValue(tok.Default)
	if v != sum {
		t.Errorf("docked-min default %g != sidebar+list-min+detail-min %g — the sum is the contract", v, sum)
	}
}

func TestDimParseLength(t *testing.T) {
	tok := DimToken{Unit: "px"}
	accept := []string{"42px", "44.5px", "1px", " 42px ", "208px", "2200px"}
	for _, s := range accept {
		if v, ok := tok.ParseValue(s); !ok || v <= 0 {
			t.Errorf("ParseValue(%q) = (%g, %v), want ok and positive", s, v, ok)
		}
	}
	reject := []string{"42", "42.25px", "0px", "-42px", "42PX", "42rem", "42 px", "", "4.2e1px", "42em", "calc(42px)", "42pxx"}
	for _, s := range reject {
		if _, ok := tok.ParseValue(s); ok {
			t.Errorf("ParseValue(%q) accepted, want refused", s)
		}
	}
}

func TestDimParseUnitless(t *testing.T) {
	tok := DimToken{Unit: "none"}
	accept := []string{"1.3", "1.15", "1.6", "1.35", "1.4", " 1.22 "}
	for _, s := range accept {
		if _, ok := tok.ParseValue(s); !ok {
			t.Errorf("ParseValue(%q) refused, want accepted", s)
		}
	}
	reject := []string{"1", "1.225", "13", "1.4px", "-1.4", "130%", "1.4.4", ""}
	for _, s := range reject {
		if _, ok := tok.ParseValue(s); ok {
			t.Errorf("ParseValue(%q) accepted, want refused", s)
		}
	}
}

func dimRejects(t *testing.T, axes map[string]map[string]string, wantSub string) {
	t.Helper()
	for _, v := range ValidateDimensions(axes) {
		if v.Severity == SeverityReject {
			if !strings.Contains(v.Message, wantSub) {
				t.Fatalf("reject message %q does not contain %q", v.Message, wantSub)
			}
			return
		}
	}
	t.Fatalf("no reject for %v (want %q)", axes, wantSub)
}

func dimNoReject(t *testing.T, axes map[string]map[string]string) {
	t.Helper()
	for _, v := range ValidateDimensions(axes) {
		if v.Severity == SeverityReject {
			t.Fatalf("unexpected reject: %+v", v)
		}
	}
}

// dimWarns asserts the judgment contract of GDK-858: a violation of wantRule
// fires as a WARN carrying wantSub, and nothing rejects. FAIL-first: the
// assertions below failed against the pre-GDK-858 source, which returned
// SeverityReject for every range and relation violation (run output in the
// round report).
func dimWarns(t *testing.T, axes map[string]map[string]string, wantRule, wantSub string) {
	t.Helper()
	found := false
	for _, v := range ValidateDimensions(axes) {
		if v.Severity == SeverityReject {
			t.Fatalf("unexpected reject for %v: %+v", axes, v)
		}
		if v.Rule == wantRule {
			found = true
			if !strings.Contains(v.Message, wantSub) {
				t.Fatalf("warn message %q does not contain %q", v.Message, wantSub)
			}
		}
	}
	if !found {
		t.Fatalf("no %s warn for %v (want %q)", wantRule, axes, wantSub)
	}
}

func TestValidateDimensionsAccepts(t *testing.T) {
	dimNoReject(t, map[string]map[string]string{
		"spacing": {"row": "48px", "row-excerpt": "60px", "control-sm": "26px"},
		"layout":  {"sidebar": "300px", "sidebar-narrow": "220px", "detail-max": "800px"},
		"type":    {"body": "14px", "body-line-height": "1.5", "micro": "12px", "title": "16px"},
	})
	dimNoReject(t, map[string]map[string]string{"type": {"heading": "28px"}})
	dimNoReject(t, map[string]map[string]string{"layout": {"shell-max": "2800px"}})
}

func TestValidateDimensionsUnknownCarried(t *testing.T) {
	vs := ValidateDimensions(map[string]map[string]string{
		"radius": {"sm": "4px"},
		"spacing": {
			"row":            "44px",
			"future-renamed": "48px",
		},
	})
	sawUnknownToken, sawUnknownAxis := false, false
	for _, v := range vs {
		if v.Severity == SeverityReject {
			t.Fatalf("unknown names must not refuse: %+v", v)
		}
		if v.Rule == "unknown-token" && v.Token == "future-renamed" {
			sawUnknownToken = true
		}
		if v.Rule == "unknown-axis" && v.Token == "radius" {
			sawUnknownAxis = true
		}
	}
	if !sawUnknownToken {
		t.Errorf("no unknown-token warning: %+v", vs)
	}
	if !sawUnknownAxis {
		t.Errorf("no unknown-axis warning: %+v", vs)
	}
}

func TestValidateDimensionsLocked(t *testing.T) {
	dimRejects(t, map[string]map[string]string{"layout": {"docked-min": "1200px"}}, "locked")
}

func TestValidateDimensionsValues(t *testing.T) {
	// The length grammar is a machine check — unparseable values still refuse.
	dimRejects(t, map[string]map[string]string{"spacing": {"row": "44"}}, "not a px length")
	// Range is a judgment (GDK-858): out-of-range values warn, carry their
	// bounds, and no longer refuse.
	dimWarns(t, map[string]map[string]string{"spacing": {"row": "60px"}}, "range", "36px–56px")
	dimWarns(t, map[string]map[string]string{"spacing": {"row": "35.9px"}}, "range", "36px–56px")
	dimWarns(t, map[string]map[string]string{"layout": {"shell-max": "1599px"}}, "range", "1600px–2800px")
	dimWarns(t, map[string]map[string]string{"type": {"body-line-height": "1.7"}}, "range", "1.15–1.6")
	dimWarns(t, map[string]map[string]string{"type": {"micro": "10.5px"}}, "range", "11px–13px")
}

func TestValidateDimensionsRelations(t *testing.T) {
	// Each relation fires from a one-sided override judged against defaults.
	dimWarns(t, map[string]map[string]string{"spacing": {"control-sm": "34px"}}, "relation", "control")
	dimWarns(t, map[string]map[string]string{"spacing": {"row-excerpt": "40px"}}, "relation", "row-excerpt") // row 36 + 8 = 44 (GDK-1336)
	dimWarns(t, map[string]map[string]string{"layout": {"detail-max": "430px"}}, "relation", "detail-max")
	dimWarns(t, map[string]map[string]string{"layout": {"overlay-max": "2300px"}}, "relation", "overlay-max")
	dimWarns(t, map[string]map[string]string{"layout": {"sidebar": "200px"}}, "relation", "sidebar")
	// Both sides overridden: the pair is judged as it renders. (The
	// pre-GDK-858 fixture 260/280 only rejected via the narrow side's RANGE;
	// the relation itself fires when the narrow step exceeds the default.)
	dimWarns(t, map[string]map[string]string{"layout": {"sidebar-narrow": "300px", "sidebar": "280px"}}, "relation", "sidebar")
	// Type steps: less than 2px between neighbors reads as noise (census Q6).
	// The warning teaches the GDK-857 move: the four rungs are one ladder.
	dimWarns(t, map[string]map[string]string{"type": {"title": "14px"}}, "relation", "2px")
	dimWarns(t, map[string]map[string]string{"type": {"micro": "13px"}}, "relation", "2px")
}

// TestRangeAndRelationValuesStillJudge pins the carry semantics that
// warn+save implies: an out-of-range value participates in the effective
// set exactly like a conforming one, so a write that breaks BOTH its range
// and a relation reports both, and the relation judges the value as it will
// render. (Pre-GDK-858 the range branch stopped before eff, which was fine
// only because the write refused anyway.)
func TestRangeAndRelationValuesStillJudge(t *testing.T) {
	// micro at 14px is above its range ceiling 13 AND body(13) no longer
	// clears micro+2 — the write lands with both warnings.
	vs := ValidateDimensions(map[string]map[string]string{"type": {"micro": "14px"}})
	sawRange, sawRelation := false, false
	for _, v := range vs {
		if v.Rule == "range" && v.Token == "micro" {
			sawRange = true
		}
		if v.Rule == "relation" {
			sawRelation = true
			if !strings.Contains(v.Message, "14px") {
				t.Errorf("relation must judge the rendered value: %q", v.Message)
			}
		}
	}
	if !sawRange || !sawRelation {
		t.Fatalf("out-of-range micro must warn range AND relation: %+v", vs)
	}
}

func TestValidateDimensionsBoundaries(t *testing.T) {
	// Inclusive bounds and exact relation edges accept. row at its own max
	// must move row-excerpt with it: the relation judges the effective set,
	// and the default excerpt (59) no longer clears row(56)+8.
	dimNoReject(t, map[string]map[string]string{"spacing": {"row": "36px"}})
	dimNoReject(t, map[string]map[string]string{"spacing": {"row": "56px", "row-excerpt": "72px"}})
	dimNoReject(t, map[string]map[string]string{"spacing": {"control-sm": "32px"}})  // == control default
	dimNoReject(t, map[string]map[string]string{"spacing": {"row-excerpt": "50px"}}) // == row+8
	dimNoReject(t, map[string]map[string]string{"type": {"micro-line-height": "1.15"}})
	dimNoReject(t, map[string]map[string]string{"type": {"heading-line-height": "1.6"}})
}

func TestDimDeterminism(t *testing.T) {
	in := map[string]map[string]string{
		"spacing": {"control": "36px", "control-sm": "28px", "row": "50px"},
		"layout":  {"sidebar": "300px"},
		"type":    {"body": "14px"},
	}
	a, b := ValidateDimensions(in), ValidateDimensions(in)
	if !reflect.DeepEqual(a, b) {
		t.Fatalf("ValidateDimensions not deterministic:\n%+v\n%+v", a, b)
	}
}
